'use strict';

let runDetails=null;
function coreOverview(){
  const active=state.employees.filter(e=>e.status==='Active'&&!e.is_sample);
  const pending=state.leave.filter(r=>r.status==='Pending'||r.status==='Cancellation pending');
  const tasks=state.tasks.filter(t=>!t.done);
  return heading('Core HR','People, time off and team records in one shared workspace.')+
    `<div class="stats">${stat('Active employees',active.length,departments().length+' departments','people')}${stat('Pending time off',pending.length,'Requests awaiting review','calendar')}${stat('Open checklist tasks',tasks.length,'Onboarding progress','checklist')}</div>`+
    `<div class="dashboard-grid"><div class="stack">${card(hr()?'Leave inbox':'Your next steps',hr()?pending.slice(0,6).map(r=>requestRow(r,'leave')).join('')||empty('No leave requests awaiting review.'):tasks.filter(t=>t.employee_id===state.user.id).map(t=>`<div class="task-row"><div class="task-info"><h3>${esc(t.title)}</h3></div><a href="#onboarding">Open checklist</a></div>`).join('')||empty('No outstanding checklist tasks.'))}${card('People by department',deptBars())}</div><div class="stack">${card('Quick actions',`<div class="card-body button-row">${addButton('Request time off','leave')}<a href="#attendance" class="btn secondary">Record attendance</a>${hr()?addButton('Add employee','employee'):''}</div>`)}${card('Your organisation',`<div class="card-body"><p>See your colleagues and reporting relationships.</p><a href="#organization" class="text-link">Open team directory</a></div>`)}</div></div>`;
}
function coreReports(){
  const real=new Set(state.employees.filter(e=>!e.is_sample).map(e=>e.id));
  return heading('Reports','Current workforce, leave and attendance records.',`<button class="btn secondary" data-action="export" data-kind="employees">Export people</button>`)+reportExportForm()+
    `<div class="stats">${stat('Active workforce',state.employees.filter(e=>real.has(e.id)&&e.status==='Active').length,'Current headcount','people')}${stat('Approved leave',state.leave.filter(r=>real.has(r.employee_id)&&r.status==='Approved').reduce((n,r)=>n+r.days,0)+' days','Recorded approved requests','calendar')}${stat('Open checklist tasks',state.tasks.filter(t=>real.has(t.employee_id)&&!t.done).length,'Onboarding progress','checklist')}</div>`+card('Workforce by department',deptBars());
}
function coreSettings(){
  const p=state.policies,limits=p.leave_limits||{Annual:24,Sick:12,Personal:6};
  return heading('Workspace policies','Configure your reviewed leave budgets and approval process.',`<div class="button-row">${addButton('Add holiday','holiday')}${addButton('Review leave allocation','leave-allocation')}</div>`)+
    card('Leave and access policy',`<form id="team-policies" class="card-body"><div class="form-grid">${selectField('Time off approval','leave_policy',[{value:'hr_only',label:'Independent HR approval'},{value:'manager_or_hr',label:'Manager or HR'},{value:'manager_then_hr',label:'Manager, then independent HR'}],p.leave_policy)}${selectField('Leave accrual','leave_accrual',[{value:'annual',label:'Annual allocation'},{value:'monthly',label:'Monthly accrual, rounded down to half days'}],p.leave_accrual)}${['Annual','Sick','Personal'].map(kind=>field(kind+' leave days per year','limit_'+kind,'number',limits[kind],'min="0" max="366" step="0.5"')).join('')}</div><label class="setup-check"><input name="require_mfa" type="checkbox" ${p.require_mfa?'checked':''}> Require authenticator MFA for everyone</label><p class="body-note">These are company policies. Review local entitlements before use. Saved requests retain their approval policy. Production requires MFA.</p><div class="form-error" role="alert"></div><button type="submit" class="btn">Save policies</button></form>`)+
    card('Company holidays',table(['Date','Country','Holiday'],(state.holidays||[]).map(h=>`<tr><td>${friendlyDate(h.date)}</td><td>${esc(h.country==='*'?'All workers':h.country)}</td><td>${esc(h.name)}</td></tr>`)))+
    card('Team leave balances',table(['Employee','Type','Entitlement','Used / reserved','Remaining'],(state.leave_balances||[]).map(b=>`<tr><td>${esc(state.employees.find(e=>e.id===b.employee_id)?.name)}</td><td>${esc(b.type)}</td><td>${b.entitlement??'Uncapped'}</td><td>${b.reserved_and_used}</td><td>${b.remaining??'Uncapped'}</td></tr>`)));
}
async function refreshTeamDetails(){
  if(!runDetails)return;
  if(runDetails.viewerId!==state.user.id||!navigationAllowed('payruns')){runDetails=null;return;}
  const runId=runDetails.run.id;
  const reviewVersion=runDetails.reviewVersion;
  runDetails=null;
  const latest=await api('/api/pay_runs/'+runId);
  runDetails={...latest,viewerId:state.user.id,reviewVersion:latest.run.version===reviewVersion?reviewVersion:null};
}
const roleLabel=role=>({employee:'Employee',manager:'Team manager',hr:'HR administrator',recruiter:'Recruiter',payroll:'Payroll reviewer',auditor:'Auditor'}[role]||'Employee');
function navigationAllowed(page){
  if(isCoreHR()&&!state.product.pages.includes(page))return false;
  const permissions={recruitment:['hr','recruiter'],payroll:['hr','payroll'],payruns:['hr','payroll'],reports:['hr'],audit:['hr','auditor'],settings:['hr'],backup:['hr']};
  return !permissions[page]||permissions[page].includes(state.user.role);
}
NAV.push(['organization','Organization','people'],['benefits','Benefits','wallet'],['learning','Learning','checklist'],['payruns','Pay runs','wallet'],['payslips','My pay statements','receipt'],['notifications','Notifications','calendar'],['security','My account','target'],['audit','Security audit','chart'],['settings','Workspace policies','checklist'],['backup','Backup & recovery','download']);

renderAuth=function(setup,ssoEnabled=false){
  const optionalCode='<label class="field">Authenticator code (if enabled)<input name="otp" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" maxlength="6" placeholder="Six-digit code"></label>'+recoveryCodeField();
  root.innerHTML=`<div class="auth-layout"><aside class="auth-story"><a class="brand" href="/">${brand()}</a><div><div class="eyebrow auth-kicker">YOUR PEOPLE. ONE WORKSPACE.</div><h1>A better day<br>for your whole team.</h1><p>Your HR workspace runs on a computer you control. Bring your team together while keeping ownership of your data.</p><div class="auth-features"><div>${icon('people')}People & teams</div><div>${icon('calendar')}Time & attendance</div>${isCoreHR()?`<div>${icon('checklist')}Onboarding checklists</div><div>${icon('people')}Reporting relationships</div>`:`<div>${icon('wallet')}Benefits & pay</div><div>${icon('target')}Goals & learning</div>`}</div></div><footer>Open-source · Self-hosted · Local data ownership</footer></aside><main class="auth-main"><div class="auth-box"><div class="eyebrow">${setup?'WELCOME TO OPENPEOPLE':'WELCOME BACK'}</div><h2>${setup?'Set up your workspace':'Sign in to your workspace'}</h2><p>${setup?'Use the one-time token in the private setup-token file shown by your local server, then create your HR account.':'Use your work email and password, or your configured identity provider.'}</p><form id="auth-form" data-setup="${setup}">${setup?field('Local setup token','setup_token','password','','autocomplete="off"')+field('Your name','name','text','','maxlength="100"')+countryFields({}):''}${field('Work email','email','email','','autocomplete="username" maxlength="254"')}${field('Password','password','password','','autocomplete="'+(setup?'new-password':'current-password')+'" maxlength="128" '+(setup?'minlength="12"':''))}${setup?'<small class="muted">Use at least 12 characters.</small>'+(isCoreHR()?'':'<label class="setup-check"><input type="checkbox" name="include_samples"> Include fictional sample records</label>'):optionalCode}<div class="form-error" role="alert"></div><button class="btn" type="submit">${setup?'Create workspace':'Sign in'}</button></form>${!setup&&ssoEnabled?'<button class="btn secondary space-top" data-team-action="sso">Sign in with your organization</button>':''}<div class="auth-help">${setup?'Sample records use fictional names and example.org addresses.':'Contact your administrator for account recovery.'}</div></div></main></div>`;
};

function baseOrganizationPage(){return heading('Organization','See reporting relationships and account roles.')+card('Your team directory',table(['Employee','Department','Reports to','Role'],state.employees.map(e=>`<tr><td>${esc(e.name)}</td><td>${esc(e.department)}</td><td>${esc(state.employees.find(p=>p.id===e.manager_id)?.name||'—')}</td><td>${esc(roleLabel(e.role))}</td></tr>`)))+`<p class="body-note muted">${hr()?'Edit a person in the People directory to set their manager or access role.':'Managers review requests for their direct reports.'}</p>`;}
function benefitsPage(){
  const plans=state.benefit_plans||[],enrollments=state.benefit_enrollments||[];
  return heading('Benefits','View available plans and manage recorded enrollments.',hr()?`<div class="button-row">${addButton('Add benefit plan','benefit')}<button class="btn secondary" data-team-action="export-benefits">Export roster page</button></div>`:null)+`<div class="section-note">Enrollment records your choice. Costs and provider coverage require separate review; no insurance purchase or payroll deduction is executed.</div><div class="goals-grid">${plans.map(p=>{const enrollment=enrollments.find(e=>e.plan_id===p.id&&e.employee_id===state.user.id&&e.status==='Active');return card(esc(p.title),`<div class="card-body"><p class="body-note">${esc(p.description)}</p><strong>${minorMoney(p.monthly_cost_paise,p.currency)} / month</strong><p class="muted">Enrollment: ${friendlyDate(p.enrollment_opens)} – ${friendlyDate(p.enrollment_closes)} (blank dates mean no limit)</p><div class="button-row space-top">${enrollment?`<button class="btn secondary" data-team-action="withdraw-benefit" data-id="${enrollment.id}">Withdraw enrollment</button>`:`<button class="btn secondary" data-team-action="enroll" data-id="${p.id}">Enroll in this plan</button>`}</div></div>`);}).join('')||empty('HR has not added benefit plans yet.')}</div>`+card(hr()?'Employee enrollments':'My enrollments',table(['Employee','Plan','Enrolled','Status','Ended'],enrollments.map(e=>`<tr><td>${esc(state.employees.find(p=>p.id===e.employee_id)?.name||'Employee')}</td><td>${esc(plans.find(p=>p.id===e.plan_id)?.title||'Plan')}</td><td>${friendlyDate(e.created_at)}</td><td>${badge(e.status||'Active')}</td><td>${friendlyDate(e.ended_on)}</td></tr>`)));
}
function learningPage(){
  const courses=state.courses||[],assignments=state.course_assignments||[];
  return heading('Learning','Assign learning and record completed courses.',hr()?`<div class="button-row">${addButton('Add course','course')}${addButton('Assign course','assignment')}</div>`:null)+card('Learning assignments',table(['Employee','Course','Due','Status',''],assignments.map(a=>`<tr><td>${esc(state.employees.find(e=>e.id===a.employee_id)?.name||'Employee')}</td><td>${esc(courses.find(c=>c.id===a.course_id)?.title||'Course')}</td><td>${friendlyDate(a.due_date)}</td><td>${badge(a.is_overdue?'Overdue':a.status)}</td><td>${hr()?`<button class="text-link" data-team-action="reassign-course" data-id="${a.id}">Reassign</button> ${a.status!=='Completed'?`<button class="text-link" data-team-action="remind-course" data-id="${a.id}">Send reminder</button>`:''} `:''}${a.employee_id===state.user.id&&a.status!=='Completed'?`<button class="text-link" data-team-action="complete-course" data-id="${a.id}">Mark completed</button>`:'—'}</td></tr>`)))+card('Course catalog',table(['Course','Description','Resource'],courses.map(c=>`<tr><td>${esc(c.title)}</td><td class="wrap-cell">${esc(c.description)}</td><td>${c.url?`<a href="${esc(c.url)}" target="_blank" rel="noopener noreferrer">Open resource</a>`:'—'}</td></tr>`)));
}
function payrollGuidance(){const catalog=countryCatalog.payroll_capabilities;return card('Country payroll planning',`<div class="card-body"><p class="body-note">Manual review and externally calculated results are available for the workspace's country options. Automatic statutory calculation, filing and payments require a validated payroll provider. The following country checklists help plan that integration.</p>${(catalog?.countries||[]).map(c=>`<details><summary>${esc(c.name)} · provider review required</summary><p class="body-note">${c.topics.map(esc).join(' · ')}</p><a href="${esc(c.url)}" target="_blank" rel="noopener noreferrer">${esc(c.authority)} guidance</a></details>`).join('')}<p class="muted body-note">Guidance reviewed ${esc(catalog?.researched_on||'—')}. Local and regional rules must be verified for each employer and pay period.</p></div>`);}
function externalPayrollDetails(p){if(!p.external_result)return '';const result=JSON.parse(p.external_result);return `<details><summary>External result · ${esc(result.provider)} · ${esc(result.reference)}</summary><p class="body-note">${esc(result.country)} ${esc(result.jurisdiction)} · Rules effective ${friendlyDate(result.rules_effective_date)}</p>${['earnings','deductions','employer_contributions'].map(group=>`<strong>${esc(group.replaceAll('_',' '))}</strong>`+table(['Component','Amount'],result[group].map(line=>`<tr><td>${esc(line.label)}</td><td>${minorMoney(line.amount_minor,p.currency)}</td></tr>`))).join('')}<p class="muted body-note">Recorded external calculation. Filing and payment occur through your provider.</p></details>`;}
function payRunsPage(){
  if(runDetails&&runDetails.viewerId!==state.user.id)runDetails=null;
  const runs=state.pay_runs||[];
  let detail='';
  if(runDetails){const run=runDetails.run;detail=card('Pay run · '+esc(payPeriodLabel(run)),`<div class="card-body"><div class="button-row">${badge(run.status)}${run.status==='Draft'?`<button class="btn" data-team-action="finalize-run" data-id="${run.id}" ${runDetails.can_finalize&&runDetails.reviewVersion===run.version?'':'disabled'}>Finalize after review</button><small>A colleague who did not create or edit this run must finalize. Another colleague must edit your own deductions.${runDetails.can_finalize&&runDetails.reviewVersion!==run.version?' Payroll changed: reopen this run and review all amounts before finalizing.':''}</small>`:''}</div></div>`+table(['Employee','Gross','Deductions','Net',''],runDetails.rows.map(p=>`<tr><td>${esc(p.employee_name)}</td><td>${minorMoney(p.gross_paise,p.currency)}</td><td>${minorMoney(p.deductions_paise,p.currency)}<small class="table-note">${esc(p.deduction_note)}</small>${externalPayrollDetails(p)}</td><td>${minorMoney(p.gross_paise-p.deductions_paise,p.currency)}</td><td>${run.status==='Draft'?(p.can_edit_deductions?`${!p.external_result?`<button class="text-link" data-team-action="deduction" data-id="${p.id}">Edit deductions</button> `:""}<button class="text-link" data-team-action="external-payroll" data-id="${p.id}">Import reviewed result</button>`:'Peer review required'):'Locked'}</td></tr>`)));}
  return heading('Pay runs','Review and preserve monthly or employer-group payroll snapshots.',`<div class="button-row">${addButton('Create monthly draft','payrun')}${addButton('Prepare dated payroll','pay-period')}</div>`)+`<div class="section-note"><strong>Reviewed payroll workspace</strong> · Draft gross pay uses effective-dated salary, calendar-day join/exit proration and approved unpaid leave. Enter checked deductions or import a reviewed external result with earnings, deductions and employer contributions. Automatic tax, filing and payments require your payroll provider.</div>`+card('Payroll runs',table(['Period','Status',''],runs.map(r=>`<tr><td>${esc(payPeriodLabel(r))}</td><td>${badge(r.status)}</td><td><button class="text-link" data-team-action="view-run" data-id="${r.id}">Open run</button></td></tr>`)))+detail+statutoryPreviewCard()+filingPacketsCard()+payrollGuidance();
}
function payslipsPage(){return heading('My pay statements','Your own finalized payroll snapshots.',`<button class="btn secondary" data-team-action="print">${icon('download')}Print / save PDF</button>`)+`<p class="body-note muted">These statements show reviewed payroll amounts. They do not certify statutory payroll compliance or confirm a bank payment.</p><div class="goals-grid">${(state.payslips||[]).map(p=>card(esc(payPeriodLabel(p))+' · '+esc(p.employee_name),`<div class="card-body"><p>${esc(p.department)}</p><dl class="statement"><dt>Gross pay</dt><dd>${minorMoney(p.gross_paise,p.currency)}</dd><dt>Deductions</dt><dd>${minorMoney(p.deductions_paise,p.currency)}</dd><dt>Net amount</dt><dd><strong>${minorMoney(p.gross_paise-p.deductions_paise,p.currency)}</strong></dd></dl><p class="muted body-note">${esc(p.deduction_note)}</p>${externalPayrollDetails(p)}</div>`)).join('')||empty('No finalized pay statements are available yet.')}</div>`;}
function notificationsPage(){return heading('Notifications','Updates about your requests, courses, and pay statements.')+card('Your updates',table(['Date','Message',''],(state.notifications||[]).map(n=>`<tr><td>${friendlyDate(n.created_at)}</td><td class="wrap-cell">${esc(n.message)}</td><td>${n.seen?'Read':`<button class="text-link" data-team-action="read-notification" data-id="${n.id}">Mark read</button>`}</td></tr>`)));}
function sessionInventory(){return card('Active sign-in sessions',table(['Signed in','Last activity','Session'],(state.sessions||[]).map(s=>`<tr><td>${friendlyDate(new Date(s.signed_in_at*1000).toISOString())} ${timeLabel(new Date(s.signed_in_at*1000).toISOString())}</td><td>${timeLabel(new Date(s.last_activity*1000).toISOString())}</td><td>${s.current?'This session':`<button class="text-link" data-team-action="revoke-session" data-id="${esc(s.id)}">Revoke session</button>`}</td></tr>`)));}
function securityPage(){const s=state.security||{};return heading('My account','Protect your account and manage local sign-in.')+sessionInventory()+`<div class="report-grid">${card('Authenticator protection',`<div class="card-body"><p><strong>${s.mfa_enabled?'Authenticator enabled':'Authenticator not enabled'}</strong></p><p class="body-note">${s.mfa_required?'Your workspace requires an authenticator.':'You can enable a time-based authenticator for local and SSO sign-in.'}</p>${!s.mfa_enabled?'<button class="btn" data-team-action="begin-mfa">Set up authenticator</button>':''}${s.mfa_enabled?`<p class="body-note">${Number(s.recovery_codes_remaining)||0} unused recovery codes.</p><button class="btn secondary" data-team-action="recovery-codes">Generate new recovery codes</button>`:''}<p class="body-note muted">Save recovery codes privately outside this computer. Each code works once. Password changes and restored backups invalidate them.</p></div>`)}${card('Change local password',`<form id="team-password" class="card-body">${field('Current password','current_password','password','','autocomplete="current-password" maxlength="128"')}${field('New password','new_password','password','','autocomplete="new-password" minlength="12" maxlength="128"')}${field('Confirm new password','confirm_password','password','','autocomplete="new-password" minlength="12" maxlength="128"')}<div class="form-error" role="alert"></div><button type="submit" class="btn">Update password</button><p class="body-note muted">This changes your OpenPeople password. Organization identity-provider passwords are managed by that provider.</p></form>`)}</div><p class="body-note muted">Sessions expire after 30 minutes of inactivity or eight hours overall. Account deactivation and role changes revoke existing sessions.</p>`;}
function settingsPage(){if(isCoreHR())return coreSettings();const p=state.policies||{},limits=p.leave_limits||{Annual:24,Sick:12,Personal:6};return heading('Workspace policies','Configure approvals, company leave budgets and expense rules.',`<div class="button-row">${addButton('Add holiday','holiday')}${addButton('Review leave allocation','leave-allocation')}</div>`)+card('Approval and access policy',`<form id="team-policies" class="card-body"><div class="form-grid">${selectField('Time off approval','leave_policy',[{value:'hr_only',label:'Independent HR approval'},{value:'manager_or_hr',label:'Manager or HR'},{value:'manager_then_hr',label:'Manager, then independent HR'}],p.leave_policy)}${selectField('Expense approval','expenses_policy',[{value:'hr_only',label:'Independent HR approval'},{value:'manager_or_hr',label:'Manager or HR'},{value:'manager_then_hr',label:'Manager, then independent HR'}],p.expenses_policy)}${selectField('Leave accrual','leave_accrual',[{value:'annual',label:'Annual allocation'},{value:'monthly',label:'Monthly accrual, rounded down to half days'}],p.leave_accrual)}${['Annual','Sick','Personal'].map(kind=>field(kind+' leave days per year','limit_'+kind,'number',limits[kind],'min="0" max="366" step="0.5"')).join('')}${selectField('Expense policy currency','expense_policy_currency',countryCatalog.currencies.length?countryCatalog.currencies:['INR'],'INR')+field('Maximum expense (selected currency)','expense_limit_rupees','number',(p.expenses_limit_paise??10000000)/100,'min="0" max="10000000" step="0.01"')}${field('Receipt required above (selected currency)','receipt_limit_rupees','number',(p.receipt_required_above_paise??250000)/100,'min="0" max="10000000" step="0.01"')}</div><label class="setup-check"><input name="require_mfa" type="checkbox" ${p.require_mfa?'checked':''}> Require authenticator MFA for everyone</label><p class="body-note muted">Enable your own authenticator first. Expense thresholds apply to the selected currency; review defaults for each country before use. These are configurable company budgets, not statutory entitlements. Explicit employee allocations can include reviewed carryover. New requests keep their saved approval policy; changes are audited.</p><div class="form-error" role="alert"></div><button type="submit" class="btn">Save policies</button></form>`)+card('Company holidays',table(['Date','Country / region','Holiday'],(state.holidays||[]).map(h=>`<tr><td>${friendlyDate(h.date)}</td><td>${esc(h.country==='*'?'All workers':h.country||'All workers')}</td><td>${esc(h.name)}</td></tr>`)))+card('Team leave balances',table(['Employee','Type','Entitlement','Used / reserved','Remaining'],(state.leave_balances||[]).map(b=>`<tr><td>${esc(state.employees.find(e=>e.id===b.employee_id)?.name)}</td><td>${esc(b.type)}</td><td>${b.entitlement??'Uncapped'}</td><td>${b.reserved_and_used}</td><td>${b.remaining??'Uncapped'}</td></tr>`)));}

function backupPage(){const b=state.backup||{},busy=['Queued','Running'].includes(b.job?.status),problem=b.configuration_error?'Configuration unreadable':b.destination_verification_required?'Destination needs verification':b.configured&&!b.destination_available?'Destination missing, unavailable, or changed':b.last_error?'Last backup failed':b.overdue?'Backup overdue':b.configured?'Configured':'Not configured';return heading('Backup & recovery','Keep encrypted recovery copies in a folder you choose.',`<button class="btn secondary" data-team-action="operations-check">Check technical readiness</button>`)+card('Encrypted cloud-folder backups',`<div class="card-body"><div class="button-row">${badge(problem)}<button class="btn" data-team-action="backup-now" ${b.configured&&b.destination_available&&!busy?'':'disabled'}>Back up now</button></div>${b.last_error?`<p role="alert" class="form-error">${esc(b.last_error)}</p>`:''}<dl class="statement"><dt>Destination last checked</dt><dd>${friendlyDate(b.destination_checked_at)} ${timeLabel(b.destination_checked_at)} · monitored every 30 seconds while host is awake</dd><dt>Current job</dt><dd>${esc(b.job?.status||'No job requested')}${b.job?.error?' · '+esc(b.job.error):''}</dd><dt>Backup interval</dt><dd>${b.interval_minutes?esc(b.interval_minutes)+' minutes':'—'}</dd><dt>Retention per configuration</dt><dd>${esc(b.retention_count||'—')} archives</dd><dt>Last successful backup</dt><dd>${b.last_success?esc(new Date(b.last_success).toLocaleString()):'No backup recorded'}</dd><dt>Last file</dt><dd class="break-anywhere">${esc(b.last_filename||'—')}</dd><dt>Cloud upload</dt><dd>${b.cloud?.configured?esc(b.cloud.status||'Not transferred yet'):'Local sync application: upload not verified here'}</dd><dt>Remote copy checksum</dt><dd class="break-anywhere">${esc(b.cloud?.sha256||'—')}</dd><dt>Recovery on another computer</dt><dd>Not verified</dd></dl><p class="body-note">Configure an available folder using the local backup command. Keep recovery passphrases separately, including phrases for older archives after rotation. Missing or replaced destinations require local reconfiguration.</p><p class="body-note muted">Only encrypted .opbackup files belong in the cloud folder. Keep the live database on the server’s local disk. Verify a downloaded archive on another computer before relying on cloud recovery. The host must be awake for scheduled backups and teammate access.</p></div>`);}
function attendanceCorrectionsPage(){return card('Attendance correction requests',table(['Employee','Proposed times ('+(state.timezone||'Asia/Kolkata')+')','Break','Reason','Status','Review'],(state.attendance_corrections||[]).map(r=>`<tr><td>${esc(state.employees.find(e=>e.id===r.employee_id)?.name||'Employee')}</td><td>${friendlyDate(r.check_in)} ${timeLabel(r.check_in)} – ${timeLabel(r.check_out)}</td><td>${esc(r.break_minutes)} min</td><td class="wrap-cell">${esc(r.reason)}</td><td>${badge(r.status)}</td><td>${r.status==='Pending'&&r.employee_id!==state.user.id&&r.created_by!==state.user.id&&(hr()||state.user.role==='manager')?`<button class="text-link" data-team-action="review-attendance" data-id="${r.id}" data-status="Approved">Approve correction</button> <button class="text-link" data-team-action="review-attendance" data-id="${r.id}" data-status="Rejected">Reject</button>`:'—'}</td></tr>`)));}

function auditPage(){return heading('Security audit','Recent authentication events and recorded data changes.',`<button class="btn secondary" data-team-action="export-audit">Export audit page</button><button class="btn secondary" data-team-action="verify-audit">Verify & export audit anchor</button>`)+card('Security events',table(['Time','Account','Event','Address'],(state.security_events||[]).map(e=>`<tr><td>${friendlyDate(e.created_at)} ${timeLabel(e.created_at)}</td><td>${esc(e.actor_name||'Unknown / local recovery')}</td><td>${esc(e.action)}</td><td>${esc(e.address)}<details><summary>Outcome details</summary><pre class="audit-detail">${esc(e.details||'{}')}</pre></details></td></tr>`)))+card('Change history',table(['Time','Actor','Action','Record','Changes'],(state.audit||[]).map(a=>`<tr><td>${friendlyDate(a.created_at)}</td><td>${esc(a.actor_name)}</td><td>${esc(a.action)}</td><td>${esc(a.entity)} #${a.entity_id||'—'}</td><td class="wrap-cell"><details><summary>View history</summary><pre class="audit-detail">${esc(a.details||'{}')}</pre></details></td></tr>`)))+`<p class="body-note muted">Most recent 100 events. Local logs are included in encrypted backups; they are not independent tamper-proof storage.</p>`;}

function teamForm(kind,id){
  if(kind==='pay-group')return {title:'Add employer pay group',path:'/api/pay_groups',content:selectField('Legal employer','legal_entity_id',(state.legal_entities||[]).map(e=>({value:e.id,label:e.name})))+field('Group name','name','text','','maxlength="100"')+selectField('Regular frequency','frequency',['weekly','fortnightly','semimonthly','monthly'],'weekly')};
  if(kind==='pay-group-member'){const groups=state.pay_groups||[],workers=state.employees.filter(e=>!e.is_sample);return {title:'Assign payroll group',path:'/api/pay_group_members',content:selectField('Pay group','pay_group_id',groups.map(g=>({value:g.id,label:g.name})))+selectField('Employee','employee_id',workers.map(e=>({value:e.id,label:e.name})))+`<input type="hidden" name="expected_group_version" value="${groups[0]?.version||1}"><input type="hidden" name="expected_employee_version" value="${workers[0]?.version||1}"><p class="body-note full">Assign this employee to the group's employer and currency first. Changing membership advances worker and group versions. Existing pay statements retain their original period and employer.</p>`};}
  if(kind==='pay-period'){const groups=state.pay_groups||[],defaults=periodDefaults(groups[0]);return {title:'Prepare dated payroll',path:'/api/pay_period_runs',content:selectField('Pay group','pay_group_id',groups.map(g=>({value:g.id,label:g.name})))+`<input type="hidden" name="expected_group_version" value="${groups[0]?.version||1}">`+field('Period start','period_start','date',defaults.start)+field('Period end','period_end','date',defaults.end)+field('Actual pay date','pay_date','date',defaults.end)+selectField('Run kind','run_kind',['regular','bonus','adjustment'],'regular')+field('Unique reference','reference','text','','maxlength="64" pattern="[A-Z0-9_-]+"')+`<p class="body-note full">Confirm dates and roster. Regular estimates prorate calendar-month salary; bonus/adjustment estimates start at zero. Every included worker requires an independently reviewed external result before finalization. No tax filing or bank payment is made.</p>`};}

  if(kind==='legal-entity')return {title:'Add legal employer',path:'/api/legal_entities',content:field('Employer code','code','text','','pattern="[A-Z0-9_-]{1,40}" maxlength="40"')+field('Legal employer name','name','text','','maxlength="100"')+selectField('Country','country',countryCatalog.countries.map(c=>({value:c.code,label:c.name})),state.country)+selectField('Currency','currency',countryCatalog.currencies,state.currency)+field('Employer registration reference','employer_reference','text','','maxlength="100"')};
  if(kind==='cost-center')return {title:'Add cost center',path:'/api/cost_centers',content:selectField('Legal employer','legal_entity_id',(state.legal_entities||[]).map(e=>({value:e.id,label:e.name})))+field('Code','code','text','','maxlength="40"')+field('Name','name','text','','maxlength="100"')};
  if(kind==='employer-assignment'){const workers=state.employees.filter(e=>!e.is_sample);return {title:'Assign employer and cost center',path:'/api/employee_assignments',content:selectField('Employee','employee_id',workers.map(e=>({value:e.id,label:e.name})))+selectField('Legal employer','legal_entity_id',(state.legal_entities||[]).map(e=>({value:e.id,label:e.name})))+selectField('Cost center','cost_center_id',(state.cost_centers||[]).map(c=>({value:c.id,label:c.code+' · '+c.name})))+`<input type="hidden" name="expected_version" value="${workers[0]?.version||1}"><p class="body-note full">Country and currency must match. The assignment is captured when a new pay run is created. Existing payroll snapshots remain unchanged.</p>`};}
  if(kind==='filing-packet'){const runs=(state.pay_runs||[]).filter(r=>r.status==='Finalized');return {title:'Prepare filing workpaper',path:'/api/filing_packets',content:selectField('Finalized payroll','run_id',runs.map(r=>({value:r.id,label:r.month})))+selectField('Legal employer','legal_entity_id',(state.legal_entities||[]).map(e=>({value:e.id,label:e.name})))+`<input type="hidden" name="expected_version" value="${runs[0]?.version||1}"><p class="body-note full">Every included worker needs an externally reviewed result and an employer assignment captured in this run. This prepares a private workpaper for your provider; it does not submit a government form.</p>`};}
  if(kind==='filing-review'||kind==='filing-evidence'){const packet=state.filing_packets.find(p=>p.id===Number(id));if(!packet)return null;const review=kind==='filing-review';return {title:review?'Review filing workpaper':'Record external filing evidence',path:'/api/filing_packets/'+packet.id,method:'PATCH',content:`<input type="hidden" name="expected_version" value="${packet.version}">`+(review?'<input type="hidden" name="status" value="Reviewed">'+field('Independent review note','review_note','text','','maxlength="500"'):selectField('External status','status',packet.status==='Reviewed'?['Submitted externally']:['Accepted externally','Rejected externally'])+field('Provider or authority receipt reference','external_reference','text','','maxlength="200"')+field('Retained receipt SHA-256','receipt_sha256','text','','pattern="[0-9a-f]{64}" maxlength="64"'))+`<p class="body-note full">Packet checksum: ${esc(packet.sha256)}. Recorded external evidence is not automatically verified with the authority. Export and reconcile the packet before reviewing.</p>`};}
  if(kind==='holiday')return {title:'Add company holiday',path:'/api/holidays',content:selectField('Applies to','country',[{value:'*',label:'All workers'},...countryCatalog.countries.map(c=>({value:c.code,label:c.name}))],'*')+field('Date','date','date',state.today)+field('Holiday name','name','text','','maxlength="100"')};
  if(kind==='leave-allocation')return {title:'Review employee leave allocation',path:'/api/leave_allocations',content:ownerField()+field('Year','year','number',state.today.slice(0,4),'min="1900" max="9998"')+selectField('Leave type','type',['Annual','Sick','Personal'])+field('Allocated days','days','number',0,'min="0" max="366" step="0.5"')+field('Reviewed carryover days','carryover','number',0,'min="0" max="366" step="0.5"')+field('Review reason','reason','text','','maxlength="500"')};
  if(kind==='reassign-course')return {title:'Reassign learning course',path:'/api/course_assignments/'+id,method:'PATCH',content:'<input type="hidden" name="action" value="reassign">'+field('New due date','due_date','date',state.today)+field('Reason','reason','text','','maxlength="500"')};
  if(kind==='reconcile-expense')return {title:'Record external expense reconciliation',path:'/api/expenses/'+id,method:'PATCH',content:'<p class="body-note">Confirm the reimbursement externally before recording its reference here.</p>'+field('Reimbursement / ledger reference','reconciliation_reference','text','','maxlength="500"')};
  if(kind==='attendance-correction'){const a=state.attendance.find(a=>a.id===Number(id));if(!a)return null;const worker=state.employees.find(e=>e.id===a.employee_id);const local=value=>value?value.slice(0,16):'';return {title:'Request attendance correction ('+(worker?.timezone||state.timezone||'Asia/Kolkata')+')',path:'/api/attendance_corrections',content:`<input type="hidden" name="attendance_id" value="${a.id}"><input type="hidden" name="expected_version" value="${a.version}">`+field('Check-in (employee work timezone)','check_in','datetime-local',local(a.check_in))+field('Check-out (employee work timezone)','check_out','datetime-local',local(a.check_out))+field('Unpaid break minutes','break_minutes','number',a.break_minutes||0,'min="0" max="1440"')+field('Reason','reason','text','','maxlength="500"')};}
  if(kind==='benefit')return {title:'Add benefit plan',path:'/api/benefit_plans',content:selectField('Currency','currency',countryCatalog.currencies.length?countryCatalog.currencies:['INR'],state.currency||'INR')+field('Plan name','title','text','','maxlength="200"')+field('Description','description','text','','maxlength="1000"')+'<label class="field">Enrollment opens (optional)<input name="enrollment_opens" type="date"></label><label class="field">Enrollment closes (optional)<input name="enrollment_closes" type="date"></label>'+field('Monthly employee cost (selected currency)','cost_rupees','number','0','min="0" max="10000000" step="0.01"')};
  if(kind==='course')return {title:'Add learning course',path:'/api/courses',content:field('Course name','title','text','','maxlength="200"')+field('Description','description','text','','maxlength="1000"')+'<label class="field full">Resource link (optional)<input name="url" type="url" maxlength="1000" placeholder="https://"></label>'};
  if(kind==='assignment')return {title:'Assign course',path:'/api/course_assignments',content:ownerField()+selectField('Course','course_id',(state.courses||[]).map(c=>({value:c.id,label:c.title})))+field('Due date','due_date','date',state.today)};
  if(kind==='payrun')return {title:'Create draft pay run',path:'/api/pay_runs',content:field('Pay month','month','month',state.today.slice(0,7))};
  if(kind==='external-payroll'){const p=runDetails?.rows.find(p=>p.id===Number(id));if(p?.can_edit_deductions)return {title:'Import reviewed payroll · '+p.employee_name,path:'/api/pay_results/'+p.id,method:'PATCH',content:`<input type="hidden" name="expected_version" value="${runDetails.run.version}"><p class="body-note full">Use integer minor units for ${esc(p.currency)}. Complete the provider, reference, rules effective date and review note. Another colleague must finalize after reviewing the imported components.</p><button type="button" class="btn secondary full" data-team-action="external-template" data-id="${p.id}">Download result template</button><label class="field full">Reviewed result JSON<textarea name="external_result_json" rows="16" maxlength="16000" required>${esc(JSON.stringify(p.external_template,null,2))}</textarea></label>`};}
  if(kind==='deduction'){const p=runDetails?.rows.find(p=>p.id===Number(id));if(p?.can_edit_deductions)return {title:'Deductions · '+p.employee_name,path:'/api/pay_results/'+p.id,method:'PATCH',content:`<input type="hidden" name="expected_version" value="${runDetails.run.version}"><input type="hidden" name="currency" value="${esc(p.currency||'INR')}">`+field('Total deductions ('+(p.currency||'INR')+')','deduction_rupees','number',p.deductions_paise/currencyFactor(p.currency),`min="0" max="${p.gross_paise/currencyFactor(p.currency)}" step="${1/currencyFactor(p.currency)}"`)+field('Calculation / review note','deduction_note','text',p.deduction_note,'maxlength="500"')};}
  return null;
}
function showTeamForm(form){modal.innerHTML=`<div class="dialog-header"><h2 id="dialog-title">${esc(form.title)}</h2><button class="icon-button" data-action="close" aria-label="Close dialog">${icon('close')}</button></div><form id="record-form" class="dialog-body" data-path="${form.path}" data-method="${form.method||'POST'}"><div class="form-grid">${form.content}</div><div class="form-error" role="alert"></div><div class="form-actions"><button type="button" class="btn secondary" data-action="close">Cancel</button><button type="submit" class="btn">Save</button></div></form>`;modal.showModal();}
async function showAuthenticator(){const enrollment=await api('/api/mfa/begin','POST',{});modal.innerHTML=`<div class="dialog-header"><h2 id="dialog-title">Set up your authenticator</h2><button class="icon-button" data-action="close" aria-label="Close dialog">${icon('close')}</button></div><form id="team-factor-confirm" class="dialog-body"><p class="body-note">Add a new time-based account in your authenticator using this secret. Keep it private.</p><code class="authenticator-secret">${esc(enrollment.secret)}</code><p class="muted body-note">Issuer: OpenPeople · Six digits · 30 seconds</p>${field('Authenticator code','otp','text','','inputmode="numeric" pattern="[0-9]{6}" maxlength="6" autocomplete="one-time-code"')}<div class="form-error" role="alert"></div><button type="submit" class="btn">Enable authenticator</button></form>`;modal.showModal();}
function recoveryCodeField(){return '<label class="field">Recovery code (use instead of authenticator code)<input name="recovery_code" autocomplete="off" maxlength="35" pattern="[0-9a-f]{8}(-[0-9a-f]{8}){3}" placeholder="xxxxxxxx-xxxxxxxx-xxxxxxxx-xxxxxxxx"></label>'; }
function renderFactorGate(setup){root.innerHTML=`<main class="factor-gate"><div class="card card-body"><h1>${setup?'Protect your account':'Verify your authenticator'}</h1><p class="body-note">${setup?'Your workspace requires authenticator enrollment before accessing HR data.':'Enter a current authenticator code to finish organization sign-in.'}</p>${setup?'<button class="btn" data-team-action="begin-mfa">Set up authenticator</button>':`<form id="team-factor-verify"><label class="field">Authenticator code<input name="otp" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" autocomplete="one-time-code"></label>${recoveryCodeField()}<div class="form-error" role="alert"></div><button class="btn" type="submit">Verify</button></form>`}<button class="btn secondary space-top" data-action="logout">Sign out</button></div></main>`;}

document.addEventListener('click',async event=>{
  const button=event.target.closest('[data-team-action]');if(!button)return;
  const action=button.dataset.teamAction;
  try{
    if(action==='dismiss-recovery-codes'){modal.close();modal.innerHTML='';return;}
    if(action==='recovery-codes'){modal.innerHTML=`<div class="dialog-header"><h2>Generate recovery codes</h2><button class="icon-button" data-action="close" aria-label="Close dialog">${icon('close')}</button></div><form id="team-recovery-codes" class="dialog-body"><p>Generating new codes invalidates all previous codes. Sign in again if more than five minutes have passed, then enter a fresh authenticator code.</p>${field('Authenticator code','otp','text','','inputmode="numeric" pattern="[0-9]{6}" maxlength="6" autocomplete="one-time-code"')}<div class="form-error" role="alert"></div><button class="btn" type="submit">Generate codes</button></form>`;modal.showModal();return;}
    if(action==='print'){window.print();return;}
    if(['reassign-course','reconcile-expense'].includes(action)){showTeamForm(teamForm(action,button.dataset.id));return;}
    if(action==='attendance-correction'){showTeamForm(teamForm(action,button.dataset.id));return;}
    if(['deduction','external-payroll'].includes(action)){const form=teamForm(action,button.dataset.id);if(form)showTeamForm(form);return;}
    if(['filing-review','filing-evidence'].includes(action)){showTeamForm(teamForm(action,button.dataset.id));return;}
    if(action==='statutory-preview'){const config=await api('/api/statutory');modal.dataset.statTemplates=JSON.stringify(config.input_templates);modal.innerHTML=`<div class="dialog-header"><h2>Dated statutory component preview</h2><button class="icon-button" data-action="close" aria-label="Close dialog">${icon('close')}</button></div><form id="team-statutory" class="dialog-body"><p class="body-note">US federal withholding/FICA or UK National Insurance only. Review the selected pack's scope, eligibility and omitted obligations. These previews do not save or finalize payroll.</p>${selectField('Rule pack','rule_country',[{value:'US',label:'US federal · 2026'},{value:'GB',label:'UK Class 1 NI · 2026/27'}],'US')}<label class="field">Calculation inputs<textarea name="inputs" rows="18" maxlength="12000" required>${esc(JSON.stringify(config.input_template,null,2))}</textarea></label><div class="form-error" role="alert"></div><button class="btn" type="submit">Calculate partial preview</button><pre id="statutory-output" class="audit-detail"></pre></form>`;modal.showModal();return;}
    if(action==='payroll-access'){const member=(state.payroll_access||[]).find(m=>m.employee_id===Number(button.dataset.id));if(!member)return;modal.innerHTML=`<div class="dialog-header"><h2>Payroll access · ${esc(member.name)}</h2><button class="icon-button" data-action="close" aria-label="Close dialog">${icon('close')}</button></div><form id="team-access" class="dialog-body" data-member="${member.employee_id}" data-version="${member.version}">${selectField('Access','mode',[{value:'restricted',label:'Selected employers only'},{value:'all',label:'All employers in this workspace'}],member.mode)}${(state.legal_entities||[]).map(e=>`<label class="setup-check"><input type="checkbox" name="entity_ids" value="${e.id}" ${member.entity_ids.includes(e.id)?'checked':''}> ${esc(e.name)}</label>`).join('')}<p class="body-note">Restricted access hides other employers' salary previews, pay results and filing packets. Unassigned workers are excluded. HR administrators retain workspace access. Saving revokes this payroll member's sessions. Sign in again if your authentication is older than five minutes.</p><div class="form-error" role="alert"></div><button class="btn" type="submit">Save payroll access</button></form>`;modal.showModal();return;}
    if(action==='operations-check'){const result=await api('/api/operations');modal.innerHTML=`<div class="dialog-header"><h2>Technical production checks</h2><button class="icon-button" data-action="close" aria-label="Close dialog">${icon('close')}</button></div><div class="dialog-body"><p>These cached checks do not approve payroll laws or off-device recovery.</p>${table(['Check','Status'],Object.entries(result.checks).map(([key,value])=>`<tr><td>${esc(key.replaceAll('_',' '))}</td><td>${value?'Passed':'Needs attention'}</td></tr>`))}<p class="body-note">Full database/audit verification runs at production startup or through the stopped-workspace command. External recovery and employer acceptance remain required.</p></div>`;modal.showModal();return;}
    if(action==='verify-audit'){const anchor=await api('/api/audit/verify');if(!anchor.passed)throw new Error('Audit verification failed. Preserve the database and investigate.');downloadJSON(anchor,'audit-anchor');toast('Audit chains verified. Keep this anchor separately to check future recovery or rollback.');return;}
    if(action==='external-template'){const p=runDetails?.rows.find(p=>p.id===Number(button.dataset.id));if(p?.external_template)downloadJSON(p.external_template,'external-payroll-result');return;}
    button.disabled=true;
    if(action==='sso'){const result=await api('/api/sso/start');location.assign(result.url);}
    if(action==='begin-mfa')await showAuthenticator();
    if(action==='view-run'){const opened=await api('/api/pay_runs/'+button.dataset.id);runDetails={...opened,viewerId:state.user.id,reviewVersion:opened.run.version};render();}
    if(action==='export-filing'){downloadJSON(await api('/api/filing_packets/'+button.dataset.id+'/export'),'private-filing-workpaper');}
    if(action==='remove-assignment'){const row=state.employee_assignments.find(r=>r.id===Number(button.dataset.id)),worker=state.employees.find(e=>e.id===row?.employee_id);if(worker)await mutate('/api/employee_assignments/'+row.id,'PATCH',{remove:true,expected_version:worker.version},'Employer assignment removed. Existing payroll snapshots retain their assignment.');}
    if(action==='revoke-session')await mutate('/api/sessions/'+button.dataset.id,'PATCH',{revoke:true},'Session revoked.');
    if(action==='remind-course')await mutate('/api/course_assignments/'+button.dataset.id,'PATCH',{action:'remind'},'Learning reminder sent.');
    if(action==='export-audit'){downloadJSON(await api('/api/audit/export?limit=500'),'audit-page');}
    if(action==='export-benefits'){downloadJSON(await api('/api/benefits/export?limit=500'),'benefit-enrollments-page');}
    if(action==='withdraw-benefit')await mutate('/api/benefit_enrollments/'+button.dataset.id,'PATCH',{status:'Withdrawn'},'Enrollment withdrawn.');
    if(action==='review-attendance')await mutate('/api/attendance_corrections/'+button.dataset.id,'PATCH',{status:button.dataset.status},'Attendance correction '+button.dataset.status.toLowerCase()+'.');
    if(action==='enroll')await mutate('/api/benefit_enrollments','POST',{plan_id:Number(button.dataset.id)},'Enrollment recorded.');
    if(action==='complete-course')await mutate('/api/course_assignments/'+button.dataset.id,'PATCH',{},'Course completed.');
    if(action==='read-notification')await mutate('/api/notifications/'+button.dataset.id,'PATCH',{},'Notification marked read.');
    if(action==='finalize-run'){if(!runDetails?.can_finalize||runDetails.reviewVersion!==runDetails.run.version||runDetails.run.id!==Number(button.dataset.id))throw new Error('Open the current run and review it before finalizing.');await mutate('/api/pay_runs/'+button.dataset.id,'PATCH',{status:'Finalized',expected_version:runDetails.reviewVersion},'Pay run finalized.');runDetails={...await api('/api/pay_runs/'+button.dataset.id),viewerId:state.user.id};render();}
    if(action==='backup-now')await mutate('/api/backup/run','POST',{},'Backup queued. Check Backup & recovery for completion.');
  }catch(error){toast(error.message);}finally{button.disabled=false;}
});
document.addEventListener('submit',async event=>{
  const form=event.target;if(!form.id.startsWith('team-'))return;event.preventDefault();
  const button=form.querySelector('button[type=submit]'),errorBox=form.querySelector('.form-error');button.disabled=true;if(errorBox)errorBox.textContent='';
  try{
    const data=Object.fromEntries(new FormData(form));
    if(form.id==='team-recovery-codes'){const result=await api('/api/mfa/recovery-codes','POST',data);modal.dataset.privateRecovery='true';modal.innerHTML=`<div class="dialog-header"><h2>Save your recovery codes</h2></div><div class="dialog-body"><p>Shown once. Copy these to private storage outside this computer. Each requires your password or organization sign-in and works once. All previous codes are invalid.</p><pre class="audit-detail" id="recovery-code-output">${result.codes.map(esc).join('\n')}</pre><button class="btn" data-team-action="dismiss-recovery-codes">I have saved my codes</button></div>`;await refresh();}
    if(form.id==='team-access'){await mutate('/api/payroll_access/'+form.dataset.member,'POST',{mode:data.mode,entity_ids:data.mode==='restricted'?[...form.querySelectorAll('[name=entity_ids]:checked')].map(e=>Number(e.value)):[],expected_version:Number(form.dataset.version)},'Payroll access saved. Member sessions revoked.',null,()=>modal.close());}
    if(form.id==='team-statutory'){const result=await api('/api/statutory/preview','POST',JSON.parse(data.inputs));document.querySelector('#statutory-output').textContent=JSON.stringify(result,null,2);}
    if(form.id==='team-report'){const query=new URLSearchParams(data);downloadJSON(await api('/api/reports?'+query),'report-'+data.entity+'-page-'+(data.offset||0));toast('Report page exported. Increase offset for the next page.');}
    if(form.id==='team-password'){if(data.new_password!==data.confirm_password)throw new Error('New passwords do not match.');const result=await api('/api/password','POST',data);csrf=result.csrf;await refresh();toast('Password changed. Other sessions were revoked.');}
    if(form.id==='team-policies'){data.require_mfa=form.querySelector('[name=require_mfa]').checked;data.leave_limits={};for(const kind of ['Annual','Sick','Personal']){data.leave_limits[kind]=Number(data['limit_'+kind]);delete data['limit_'+kind];}if(!isCoreHR()){data.expenses_limit_paise=Math.round(Number(data.expense_limit_rupees)*currencyFactor(data.expense_policy_currency));data.receipt_required_above_paise=Math.round(Number(data.receipt_limit_rupees)*currencyFactor(data.expense_policy_currency));delete data.expense_limit_rupees;delete data.receipt_limit_rupees;}await mutate('/api/policies','POST',data,'Workspace policies saved.');}
    if(form.id==='team-factor-confirm'||form.id==='team-factor-verify'){await api(form.id==='team-factor-confirm'?'/api/mfa/confirm':'/api/mfa/verify','POST',data);modal.close();await start();toast('Authenticator verified.');}
  }catch(error){if(errorBox)errorBox.textContent=error.message;else toast(error.message);}finally{button.disabled=false;}
});

document.addEventListener('change',event=>{const input=event.target,form=input.closest('#record-form');if(!form)return;const version=form.querySelector('[name=expected_version]');if(!version)return;if(form.dataset.path==='/api/employee_assignments'&&input.name==='employee_id')version.value=state.employees.find(e=>e.id===Number(input.value))?.version||'';if(form.dataset.path==='/api/filing_packets'&&input.name==='run_id')version.value=state.pay_runs.find(r=>r.id===Number(input.value))?.version||'';});

function organizationPage(){if(isCoreHR())return baseOrganizationPage();return baseOrganizationPage()+payrollAccessCard()+payGroupsCard()+(hr()?card('Legal employers & cost centers',`<div class="card-body"><div class="button-row">${addButton('Add employer','legal-entity')}${addButton('Add cost center','cost-center')}${addButton('Assign employee','employer-assignment')}</div><p class="body-note">Assign real employees before creating a pay run. Employer and cost-center records are shared within this workspace; organization access uses the existing HR and payroll roles.</p></div>`+table(['Code','Employer','Country','Currency'],(state.legal_entities||[]).map(e=>`<tr><td>${esc(e.code)}</td><td>${esc(e.name)}</td><td>${esc(e.country)}</td><td>${esc(e.currency)}</td></tr>`))+table(['Employee','Employer','Cost center',''],(state.employee_assignments||[]).map(a=>`<tr><td>${esc(state.employees.find(e=>e.id===a.employee_id)?.name||'Employee')}</td><td>${esc(state.legal_entities.find(e=>e.id===a.legal_entity_id)?.name||'—')}</td><td>${esc(state.cost_centers.find(c=>c.id===a.cost_center_id)?.name||'—')}</td><td><button class="text-link" data-team-action="remove-assignment" data-id="${a.id}">Remove assignment</button></td></tr>`))):'');}
function statutoryPreviewCard(){return card('Dated statutory preview',`<div class="card-body"><p class="body-note">US federal withholding/FICA · 2026; UK Class 1 National Insurance · 2026/27. Component calculations only. Independent payroll review and other jurisdictional calculations remain required.</p><button class="btn secondary" data-team-action="statutory-preview">Open component preview</button></div>`);}
function filingPacketsCard(){return card('Filing workpapers & external evidence',`<div class="card-body">${addButton('Prepare workpaper','filing-packet')}<p class="body-note">Exports contain private payroll information. They are provider-neutral reconciliation packets, not government submission files. Submit through your authorized provider and retain its receipts separately. Authority acceptance is not verified here.</p></div>`+table(['Packet','Employer','Status','Actions'],(state.filing_packets||[]).map(p=>`<tr><td>#${p.id}<small class="table-note">Version ${p.version}</small></td><td>${esc(state.legal_entities.find(e=>e.id===p.legal_entity_id)?.name||'—')}</td><td>${badge(p.status)}</td><td><button class="text-link" data-team-action="export-filing" data-id="${p.id}">Export</button> ${p.can_review?`<button class="text-link" data-team-action="filing-review" data-id="${p.id}">Independent review</button>`:''}${['Reviewed','Submitted externally'].includes(p.status)?`<button class="text-link" data-team-action="filing-evidence" data-id="${p.id}">Record external evidence</button>`:''}</td></tr>`)));}

function downloadJSON(data,name){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download='openpeople-'+name+'-'+state.today+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function reportExportForm(){return card('Export a dated report page',`<form id="team-report" class="card-body"><div class="form-grid">${selectField('Report','entity',isCoreHR()?['employees','leave','attendance']:['employees','leave','expenses','attendance','benefit_enrollments'])}${field('From','start','date',state.today.slice(0,4)+'-01-01')}${field('To','end','date',state.today)}${field('Page size','limit','number',100,'min="1" max="500"')}${field('Offset','offset','number',0,'min="0" max="1000000"')}</div><p class="body-note muted">Demo workers are excluded. Export includes the total count; add page size to offset for the next page. Employee dates use joining date; attendance uses work date; expenses use claim date.</p><div class="form-error" role="alert"></div><button class="btn">Export report page</button></form>`);}
function openAmendment(entity,id){const row=state[entity].find(r=>r.id===Number(id));if(!row)return;const fields=entity==='leave'?selectField('Leave type','type',['Annual','Sick','Personal','Unpaid'],row.type)+field('Start','start_date','date',row.start_date)+field('End','end_date','date',row.end_date)+`<label class="setup-check field"><input type="checkbox" name="half_day" ${row.days===0.5?'checked':''}> Half day</label>`:field('Description','description','text',row.description,'maxlength="500"')+field('Amount (₹)','amount','number',row.amount_paise/currencyFactor(row.currency),'min="0.01" step="0.01"')+selectField('Category','category',['Travel','Meals','Equipment','Other'],row.category)+field('Expense date','expense_date','date',row.expense_date)+`<label class="field">Receipt reference<input name="receipt_reference" value="${esc(row.receipt_reference)}" maxlength="500"></label>`;showTeamForm({title:'Amend pending request',path:'/api/'+entity+'/'+id,method:'PATCH',content:fields+field('Reason','reason','text',entity==='leave'?row.reason:'','maxlength="500"')});}

let lastHumanActivity=0;
async function recordHumanActivity(event){if(!event.isTrusted||!state||Date.now()-lastHumanActivity<60000)return;lastHumanActivity=Date.now();try{await api('/api/activity','POST',{});}catch(error){toast(error.message);}}
document.addEventListener('pointerdown',recordHumanActivity);document.addEventListener('keydown',recordHumanActivity);

setInterval(async()=>{if(!state||document.visibilityState!=='visible'||modal.open||document.activeElement?.closest('form'))return;try{const changes=await api('/api/changes');if(changes.revision!==state.revision)await refresh();}catch(error){const status=document.querySelector('.sidebar-footer');if(status)status.textContent='Connection interrupted · Reconnecting automatically';}},15000);

function payrollAccessCard(){return hr()?card('Payroll operator access',table(['Operator','Access',''],(state.payroll_access||[]).map(m=>`<tr><td>${esc(m.name)}</td><td>${m.mode==='all'?'All workspace employers':esc(m.entity_ids.map(id=>state.legal_entities.find(e=>e.id===id)?.name||'Employer').join(', ')||'No employers')}</td><td><button class="text-link" data-team-action="payroll-access" data-id="${m.employee_id}">Change access</button></td></tr>`))):'';}
document.addEventListener('change',event=>{if(event.target.name==='rule_country'&&event.target.closest('#team-statutory')){const templates=JSON.parse(modal.dataset.statTemplates||'{}');event.target.form.elements.inputs.value=JSON.stringify(templates[event.target.value],null,2);document.querySelector('#statutory-output').textContent='';}});

function payPeriodLabel(run){return run.pay_group_id?`${run.pay_group_name||'Pay group'} · ${run.period_start} – ${run.period_end} · ${run.run_kind}`:run.month;}
function periodDefaults(group){const day=state.today,number=Number(day.slice(8)),year=Number(day.slice(0,4)),month=Number(day.slice(5,7)),last=new Date(Date.UTC(year,month,0)).toISOString().slice(0,10);if(group?.frequency==='monthly')return {start:day.slice(0,8)+'01',end:last};if(group?.frequency==='semimonthly')return {start:day.slice(0,8)+(number<=15?'01':'16'),end:number<=15?day.slice(0,8)+'15':last};const end=new Date(day+'T12:00:00Z');end.setUTCDate(end.getUTCDate()+(group?.frequency==='fortnightly'?13:6));return {start:day,end:end.toISOString().slice(0,10)};}
function payGroupsCard(){if(!['hr','payroll'].includes(state.user.role))return '';return card('Employer pay groups',`<div class="card-body">${hr()?`<div class="button-row">${addButton('Add pay group','pay-group')}${addButton('Assign group member','pay-group-member')}</div>`:''}<p class="body-note">Dated payroll keeps group versions and employer snapshots. Weekly, fortnightly, semimonthly and monthly groups require reviewed external results.</p></div>`+table(['Group','Employer','Frequency','Roster version'],(state.pay_groups||[]).map(g=>`<tr><td>${esc(g.name)}</td><td>${esc(state.legal_entities.find(e=>e.id===g.legal_entity_id)?.name||'Employer')}</td><td>${esc(g.frequency)}</td><td>${g.version}</td></tr>`)));}
document.addEventListener('change',event=>{const input=event.target,form=input.closest('#record-form');if(!form)return;if(input.name==='employee_id'&&form.elements.expected_employee_version)form.elements.expected_employee_version.value=state.employees.find(e=>e.id===Number(input.value))?.version||'';if(input.name==='pay_group_id'&&form.elements.expected_group_version){const group=state.pay_groups.find(g=>g.id===Number(input.value));form.elements.expected_group_version.value=group?.version||'';if(form.dataset.path==='/api/pay_period_runs'){const defaults=periodDefaults(group);form.elements.period_start.value=defaults.start;form.elements.period_end.value=defaults.end;form.elements.pay_date.value=defaults.end;}}});

modal.onclose=()=>{if(modal.dataset?.privateRecovery==='true'){modal.innerHTML='';delete modal.dataset.privateRecovery;}};
start();
